CREATE TABLE carts(id UUID PRIMARY KEY,owner_id UUID NOT NULL,status VARCHAR(30) NOT NULL,version BIGINT NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL,CONSTRAINT cart_status CHECK(status IN('ACTIVE','CHECKOUT_PENDING','CONVERTED')));
CREATE UNIQUE INDEX carts_one_open_per_owner ON carts(owner_id) WHERE status IN('ACTIVE','CHECKOUT_PENDING');
CREATE TABLE cart_items(cart_id UUID NOT NULL REFERENCES carts(id) ON DELETE CASCADE,variant_id UUID NOT NULL,quantity BIGINT NOT NULL CHECK(quantity BETWEEN 1 AND 999),created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL,PRIMARY KEY(cart_id,variant_id));
CREATE TABLE orders(id UUID PRIMARY KEY,owner_id UUID NOT NULL,source_cart_id UUID NOT NULL,checkout_idempotency_key VARCHAR(200) NOT NULL,checkout_request_hash VARCHAR(64) NOT NULL,status VARCHAR(30) NOT NULL,currency VARCHAR(3) NOT NULL,merchandise_total NUMERIC(19,2) NOT NULL,inventory_reservation_id UUID,inventory_reservation_expires_at TIMESTAMPTZ,cancellation_reason VARCHAR(200),version BIGINT NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL,UNIQUE(owner_id,checkout_idempotency_key),CONSTRAINT order_status CHECK(status IN('PENDING_INVENTORY','AWAITING_PAYMENT','CANCELLED','EXPIRED')));
CREATE TABLE order_items(id UUID PRIMARY KEY,order_id UUID NOT NULL REFERENCES orders(id),variant_id UUID NOT NULL,product_id UUID NOT NULL,product_name VARCHAR(200) NOT NULL,product_slug VARCHAR(220) NOT NULL,variant_name VARCHAR(200) NOT NULL,sku VARCHAR(100) NOT NULL,attributes JSONB NOT NULL,quantity BIGINT NOT NULL CHECK(quantity>0),unit_price NUMERIC(19,2) NOT NULL,line_total NUMERIC(19,2) NOT NULL,currency VARCHAR(3) NOT NULL);
CREATE INDEX orders_owner_created_idx ON orders(owner_id,created_at DESC);CREATE INDEX orders_status_reservation_expiry_idx ON orders(status,inventory_reservation_expires_at);CREATE INDEX orders_status_created_idx ON orders(status,created_at);
